+paused_at :: proc(pauses: []Pause_Event, wall_tick: u64, logic_hz: i32) -> bool {
+	paused := false
+	for p in pauses {
+		effect := u64(max(0, i64(p.at_ms) * i64(logic_hz) / 1000)) + 1
+		if effect <= wall_tick {
+			paused = p.paused
+		}
+	}
+	return paused
